mapper.select:
select pos_id as positionId, pos_title as positionTitle
from t_pos
where pos_id = #{positionId} and pos_company_id = #{companyId}


where 1 = 1

    and eqs_type = #{type}


    and eqs_difficulty = #{difficulty}


    and eqs_skill_tag like concat('%', #{skillTag}, '%')


    and eqs_content like concat('%', #{keyword}, '%')

order by eqs_id desc


where 1 = 1

    and eqs_type = #{type}


    and eqs_difficulty = #{difficulty}


    and eqs_skill_tag like concat('%', #{skillTag}, '%')


    and eqs_id not in

        #{exId}


order by rand()
limit #{limit}

select count(1) from t_exam_question
where 1 = 1

    and eqs_type = #{type}


    and eqs_difficulty = #{difficulty}


    and eqs_skill_tag like concat('%', #{skillTag}, '%')

select p.epa_id as paperId, p.epa_name as name, p.epa_position_id as positionId, pos.pos_title as positionTitle, p.epa_total_score as totalScore, p.epa_duration_min as durationMin, p.epa_rule_json as ruleJson, p.epa_status as status, date_format(p.epa_created_at, '%Y-%m-%d %H:%i') as createdAt, (select count(1) from t_exam_paper_question q where q.epq_paper_id = p.epa_id) as questionCount from t_exam_paper p join t_pos pos on pos.pos_id = p.epa_position_id where pos.pos_company_id = #{companyId}
and p.epa_position_id = #{positionId}
order by p.epa_id desc

mapper.delete:
delete p from t_exam_paper p
join t_pos pos on pos.pos_id = p.epa_position_id
where p.epa_id = #{paperId} and pos.pos_company_id = #{companyId}

mapper.select:
select s.esd_id as scheduleId, s.esd_position_id as positionId, pos.pos_title as positionTitle, s.esd_paper_id as paperId, p.epa_name as paperName, p.epa_duration_min as durationMin, p.epa_total_score as totalScore, date_format(s.esd_start_at, '%Y-%m-%d %H:%i') as startAt, date_format(s.esd_end_at, '%Y-%m-%d %H:%i') as endAt, s.esd_max_attempts as maxAttempts, s.esd_pass_threshold as passThreshold, s.esd_force_dual_camera as forceDualCamera, s.esd_dual_camera_config_json as dualCameraConfig, s.esd_submit_rule_json as submitRule, s.esd_notify_config_json as notifyConfig, s.esd_auto_flow_json as autoFlow, s.esd_status as status, date_format(s.esd_created_at, '%Y-%m-%d %H:%i') as createdAt from t_exam_schedule s join t_exam_paper p on p.epa_id = s.esd_paper_id join t_pos pos on pos.pos_id = s.esd_position_id where pos.pos_company_id = #{companyId}
and s.esd_position_id = #{positionId}
and s.esd_status = #{status}
order by s.esd_start_at desc, s.esd_id desc

mapper.update:
update t_exam_schedule
set esd_status = #{status}, esd_updated_at = now()
where esd_id = #{scheduleId}

update t_exam_schedule
set esd_notify_config_json = #{configJson}, esd_updated_at = now()
where esd_id = #{scheduleId}
